const topics = [
  'Tool Calling',
  'AI Agent Memory',
  'Multi-Agent Systems',
  'AI Evaluation',
  'Fine-Tuning',
  'LoRA',
  'AI APIs',
  'AI Automation',
  'n8n AI Agents',
  'Webhooks + AI',
  'AI Workflows',
  'Computer Vision',
  'Multimodal AI',
  'AI Security',
  'Prompt Injection',
  'RAG Security',
  'AI Cost Optimization',
  'LLM Latency',
  'Open-Source LLMs',
  'AI Coding Assistants',
  'AI in Software Development',
  'The Future of Agentic AI'
];

// New campaign starts from Tool Calling
// Day 1 = 2026-09-16
const startDate = new Date('2026-09-16T00:00:00.000Z');

const today = new Date();
today.setUTCHours(0, 0, 0, 0);

const diffMs = today.getTime() - startDate.getTime();
const dayNumber = Math.floor(diffMs / (24 * 60 * 60 * 1000)) + 1;

// Stop workflow after all topics are completed
if (dayNumber < 1 || dayNumber > topics.length) {
  return [];
}

const topic = topics[dayNumber - 1];

return [
  {
    json: {
      dayNumber,
      topic,
      date: today.toISOString().split('T')[0]
    }
  }
];
